    <div class="flex items-center gap-3 mb-5">
      <div class="w-12 h-12 rounded-xl bg-emerald-100 flex items-center justify-center">
        <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"/></svg>
      </div>
      <h3 class="text-xl font-bold text-emerald-900">Action Steps — Add timing and response checks</h3>
    </div>
    
    <div class="space-y-4">
      
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">1</div>
        <div>
          <p class="font-semibold text-slate-900">Draft your first email</p>
          <p class="text-slate-600 text-sm">Write a short, helpful email that acknowledges the enquiry and offers a booking link.</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">2</div>
        <div>
          <p class="font-semibold text-slate-900">Test your booking link</p>
          <p class="text-slate-600 text-sm">Click the calendar link to confirm it opens the correct booking page.</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">3</div>
        <div>
          <p class="font-semibold text-slate-900">Preview merge fields</p>
          <p class="text-slate-600 text-sm">Check that {{contact.first_name}} and other merge fields display correctly.</p>
        </div>
      </div>
    </div>
  </div>
</div>',
      title = 'Write the first useful email',
      lesson_number = 3,
      sort_order = 3,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Write the first useful email';
  END IF;

END $$;


-- Insert Quiz Questions for Lesson: Write the first useful email

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 17 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 17 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'write-first-useful-email' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson write-first-useful-email not found in module 17';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the single action you want the prospect to take after reading the first email?', 
    '["Visit your website homepage","Book a call or reply with a question","Follow you on social media","Download a free guide"]'::jsonb,
    'Book a call or reply with a question',
    'The first email should have one clear call to action: book a call using the calendar link, or reply with a question if they need more information first.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you test the booking URL before including it in the email?', 
    '["To make the email look more professional","To confirm it opens the intended calendar and works correctly","Because HighLevel requires URL verification","To track click-through rates"]'::jsonb,
    'To confirm it opens the intended calendar and works correctly',
    'Testing the booking URL ensures it opens the correct calendar, the times display properly, and the prospect can actually complete a booking. A broken link defeats the purpose of the follow-up.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you avoid claiming in the first email?', 
    '["That you received their enquiry","That you personally reviewed their enquiry if you have not","That you would be pleased to learn more","That they can reply with a question"]'::jsonb,
    'That you personally reviewed their enquiry if you have not',
    'Do not claim you personally reviewed an enquiry if that has not happened. Automated emails should be honest about their nature to maintain trust with the prospect.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
